-- Seed data para competencias específicas de 1er Grado del Nivel Secundario

INSERT INTO public.curr_competencias_especificas (nivel, grado, asignatura, bloque, competencia_fundamental, codigo, descriptor) VALUES
-- Lengua Española
('Secundaria', '1ro', 'Lengua Española', 'BC1', 'Comunicativa', 'CE-LE1', 'Se comunica con claridad en diferentes contextos, siguiendo los procesos de compresión y producción oral y escrita, con creatividad, al emplear adecuadamente un tipo de texto (funcional o literario), las TIC, así como otros recursos y medios.'),
('Secundaria', '1ro', 'Lengua Española', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LE2', 'Utiliza secuencias argumentativas (hechos, ejemplos, analogías, argumentos y contraargumentos), en discursos orales y escritos, creando nuevos conocimientos a partir de procesos de comprensión y producción de textos orales y escritos abordados con temas y problemas sociales de su realidad.'),
('Secundaria', '1ro', 'Lengua Española', 'BC2', 'Resolución de Problemas', 'CE-LE3', 'Identifica problemas de su vida estudiantil o cotidiana, a través de un tipo de texto específico y apropiado, como punto de partida para su estudio y solución.'),
('Secundaria', '1ro', 'Lengua Española', 'BC4', 'Ética y Ciudadana', 'CE-LE4', 'Analiza textos variados de manera oral o escrita que ponen de relieve hechos y tradiciones históricas relevantes, identificando nuevas relaciones sociales al reconocer y valorar el patrimonio natural y sociocultural dominicano.'),
('Secundaria', '1ro', 'Lengua Española', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LE7', 'Demuestra conocimiento y comprensión de sí mismo y de los demás al expresar su percepción del mundo, a través de un tipo de texto, favorable a las situaciones y a las personas.'),
('Secundaria', '1ro', 'Lengua Española', 'BC3', 'Científica y Tecnológica', 'CE-LE5', 'Demuestra conocimiento de procesos investigativos científicos sencillos y del uso de tecnología de acuerdo con su grado, a través de textos científicos y especialmente los de secuencia expositivo-explicativa.'),
('Secundaria', '1ro', 'Lengua Española', 'BC3', 'Ambiental y de la Salud', 'CE-LE6', 'Explica con claridad situaciones sobre salud, medio ambiente y la comunidad, mediante textos de diferentes secuencias y géneros, a través de herramientas tecnológicas y otros medios y recursos.'),

-- Inglés
('Secundaria', '1ro', 'Inglés', 'BC1', 'Comunicativa', 'CE-LEI1', 'Comprende y expresa ideas, sentimientos y valores culturales en distintas situaciones de comunicación orales y escritas relativas a necesidades concretas y temas cotidianos, utilizando el idioma inglés de forma breve y sencilla para compartir información propia y de otras personas, describir sus actividades cotidianas, el entorno inmediato, y sus puntos de vista.'),
('Secundaria', '1ro', 'Inglés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEI2', 'Interactúa en el idioma inglés, empleando estrategias de desempeño, el razonamiento lógico-verbal y la expresión creativa y crítica con el propósito de comunicarse de forma clara y efectiva en distintas situaciones concretas de comunicación oral y escrita.'),
('Secundaria', '1ro', 'Inglés', 'BC2', 'Resolución de Problemas', 'CE-LEI3', 'Se comunica en inglés oral y escrito de forma básica, pero comprensible, compartiendo información que permite identificar, describir y abordar problemas y situaciones comunes de su entorno inmediato.'),
('Secundaria', '1ro', 'Inglés', 'BC4', 'Ética y Ciudadana', 'CE-LEI4', 'Se comunica en intercambios breves y sencillos, participando en un plano de respeto y colaboración, e identificando algunas de las diferencias individuales y la identidad social y cultural propia y de otros países.'),
('Secundaria', '1ro', 'Inglés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEI7', 'Se comunica en el idioma inglés, con cortesía, asertividad, actitud de respeto, honestidad y aceptación al expresarse sobre sí mismo y las demás personas en cuanto a preferencias, experiencias, características personales y actividades cotidianas.'),
('Secundaria', '1ro', 'Inglés', 'BC3', 'Científica y Tecnológica', 'CE-LEI5', 'Interactúa en el idioma inglés compartiendo información, ideas y opiniones sobre aspectos científicos y tecnológicos de su entorno inmediato en distintas situaciones cotidianas de comunicación.'),
('Secundaria', '1ro', 'Inglés', 'BC3', 'Ambiental y de la Salud', 'CE-LEI6', 'Muestra preferencias por actividades cotidianas y opciones que impactan de forma positiva la salud y el medioambiente en distintas situaciones de comunicación.'),

-- Francés
('Secundaria', '1ro', 'Francés', 'BC1', 'Comunicativa', 'CE-LEF1', 'Se comunica en francés practicando previamente y con la necesaria ayuda de su interlocutor, utilizando frases y oraciones breves, relativas a situaciones inmediatas de comunicación, donde se expresa con frases de cortesía, se presenta y presenta a otras personas, describe actividades cotidianas, objetos, personas e indica la ubicación de objetos comunes en el espacio.'),
('Secundaria', '1ro', 'Francés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEF2', 'Se expresa en el idioma francés, utilizando la lógica verbal para estructurar unas cuantas frases y expresiones básicas que ensaya y presenta en distintas situaciones inmediatas de comunicación previamente planificadas, necesitando ayuda al expresarse y esfuerzo para ser comprendido.'),
('Secundaria', '1ro', 'Francés', 'BC2', 'Resolución de Problemas', 'CE-LEF3', 'Comprende y expresa informaciones relevantes para resolver problemas o situaciones de su entorno cotidiano y necesidades inmediatas de comunicación, tales como la identificación y descripción de personas, actividades cotidianas, objetos y lugares comunes, utilizando frases hechas y oraciones muy breves y sencillas, con la ayuda de su interlocutor para poder expresarse y poder ser comprendido.'),
('Secundaria', '1ro', 'Francés', 'BC4', 'Ética y Ciudadana', 'CE4-LEF4', 'Interactúa con cortesía y respeto durante intercambios muy sencillos en el idioma francés oral y escrito, identificando las diferencias individuales básicas y la identidad social y cultural propia y de otras personas, relativas a reglas de cortesía, información personal básica, actividades preferidas y descripción de objetos y lugares propios del entorno inmediato.'),
('Secundaria', '1ro', 'Francés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEF7', 'Se identifica e identifica a otras personas con cortesía, actitud de respeto y aceptación, al compartir informaciones personales básicas y actividades cotidianas y al describir objetos de su pertenencia y su ubicación en el entorno inmediato.'),
('Secundaria', '1ro', 'Francés', 'BC3', 'Científica y Tecnológica', 'CE-LEF5', 'Identifica, organiza y comparte en formato físico, digital o en línea, información relativa a la ciencia y la tecnología presentes en su entorno cotidiano, haciendo uso de un repertorio limitado de vocabulario, frases y oraciones muy breves y sencillas con ayuda de su interlocutor.'),
('Secundaria', '1ro', 'Francés', 'BC3', 'Ambiental y de la Salud', 'CE-LEF6', 'Expresa preferencia por opciones que impactan positivamente la salud y el medio ambiente, en distintas situaciones de comunicación oral y escrita, donde se identifica y describe su entorno y actividades cotidianas.'),

-- Matemática
('Secundaria', '1ro', 'Matemática', 'BC1', 'Comunicativa', 'CE-MAT1', 'Usa métodos orales, escritos, concretos, pictóricos, gráficos y el lenguaje matemático para describir situaciones del entorno.'),
('Secundaria', '1ro', 'Matemática', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE1-MAT2', 'Reconoce en el trabajo matemático, razonamientos deductivos e inductivos como soporte a planteamientos y resolución de problemas.'),
('Secundaria', '1ro', 'Matemática', 'BC2', 'Resolución de Problemas', 'CE1-MAT3', 'Utiliza un enfoque de resolución de problemas para investigar y estudiar los conocimientos matemáticos, a partir de situaciones dentro y fuera de la matemática.'),
('Secundaria', '1ro', 'Matemática', 'BC4', 'Ética y Ciudadana', 'CE-MAT4', 'Interpreta situaciones del contexto que impliquen la movilización de conocimientos e ideas matemáticas, respetando diferentes puntos de vista y asumiendo actitud responsable.'),
('Secundaria', '1ro', 'Matemática', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-MAT7', 'Exhibe una actitud responsable en la interpretación de situaciones en el quehacer matemático, respetando los diferentes puntos de vista de los demás.'),
('Secundaria', '1ro', 'Matemática', 'BC3', 'Científica y Tecnológica', 'CE-MAT5', 'Utiliza herramientas tecnológicas para la resolución de problemas diversos, integrando conocimientos matemáticos en situaciones del contexto.'),
('Secundaria', '1ro', 'Matemática', 'BC3', 'Ambiental y de la Salud', 'CE-MAT6', 'Aplica modelos matemáticos para ayudar a comprender problemas relacionados con enfermedades que afecten la salud de las personas.'),

-- Ciencias Sociales
('Secundaria', '1ro', 'Ciencias Sociales', 'BC1', 'Comunicativa', 'CE-CS1', 'Identifica en medios impresos y digitales fuentes primarias y secundarias sobre procesos sociales, políticos, económicos, culturales, históricos y geográficos; con la finalidad de obtener informaciones confiables.'),
('Secundaria', '1ro', 'Ciencias Sociales', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CS2', 'Relaciona a través de propuestas y proyectos de investigación, hechos históricos con el espacio geográfico, ocurridos en diferentes periodos, con la finalidad de desarrollar una conciencia crítica en cuanto al tiempo y el espacio.'),
('Secundaria', '1ro', 'Ciencias Sociales', 'BC2', 'Resolución de Problemas', 'CE-CS3', 'Verifica en el levantamiento de informaciones, la existencia de un problema, con la finalidad de ubicar el contexto social en el que se produce.'),
('Secundaria', '1ro', 'Ciencias Sociales', 'BC4', 'Ética y Ciudadana', 'CE-CS4', 'Realiza propuestas que promueven la interacción sociocultural, el respeto a la Constitución y la construcción ciudadana, con la finalidad de fortalecer la democracia, la cultura de paz y el respeto a los derechos humanos.'),
('Secundaria', '1ro', 'Ciencias Sociales', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CS7', 'Emplea relaciones armoniosas y equilibradas, con la finalidad de promover la construcción de la cultura de paz, fundamentada en el respeto hacia uno mismo y hacia los demás.'),
('Secundaria', '1ro', 'Ciencias Sociales', 'BC3', 'Científica y Tecnológica', 'CE-CS5', 'Utiliza sus habilidades al analizar planteamientos y teorías científicas en sus investigaciones, tanto en el ámbito de los fenómenos naturales como sociales, con la finalidad de proporcionar explicaciones fundamentadas y rigurosas.'),
('Secundaria', '1ro', 'Ciencias Sociales', 'BC3', 'Ambiental y de la Salud', 'CE-CS6', 'Analiza críticamente las acciones humanas que pueden poner en riesgo los estilos de vida saludables y el equilibrio ambiental, con la finalidad de comprender sus efectos sobre la sociedad y la naturaleza.'),

-- Ciencias de la Naturaleza
('Secundaria', '1ro', 'Ciencias de la Naturaleza', 'BC1', 'Comunicativa', 'CE-CN1', 'Se comunica utilizando el lenguaje científico y tecnológico de ciencias de la tierra y el universo que implica sus ideas básicas a respuestas a preguntas y situaciones de problemas simulados y reales.'),
('Secundaria', '1ro', 'Ciencias de la Naturaleza', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CN2', 'Ofrece explicaciones científicas y tecnológicas a problemas y fenómenos naturales relacionados a Ciencias de la Tierra y el Universo.'),
('Secundaria', '1ro', 'Ciencias de la Naturaleza', 'BC2', 'Resolución de Problemas', 'CE-CN3', 'Aplica procedimientos científicos y tecnológicos, básicos y organizados para solucionar problemas o dar respuestas a fenómenos naturales relacionados con Ciencias de la Tierra y el Universo.'),
('Secundaria', '1ro', 'Ciencias de la Naturaleza', 'BC4', 'Ética y Ciudadana', 'CE-CN4', 'Analiza la naturaleza de las ciencias naturales y el alcance del desarrollo tecnológico en nuestra sociedad relacionada con Ciencias de la Tierra y el Universo, sus aportes y reflexiones éticas.'),
('Secundaria', '1ro', 'Ciencias de la Naturaleza', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CN7', 'Gestiona actitudes intelectuales, emocionales y conductuales proactivas al desarrollo de su proyección personal desde las Ciencias de la Tierra y el Universo.'),
('Secundaria', '1ro', 'Ciencias de la Naturaleza', 'BC3', 'Científica y Tecnológica', 'CE-CN5', 'Se cuestiona e identifica problemas y situaciones y les da explicación, utilizando ideas y procesos fundamentales de las Ciencias de la Tierra y el Universo.'),
('Secundaria', '1ro', 'Ciencias de la Naturaleza', 'BC3', 'Ambiental y de la Salud', 'CE-CN6', 'Actúa con responsabilidad crítica y autónoma para el cuidado de su salud y ambientales relacionadas con Ciencias de la Tierra y el Universo.'),

-- Educación Artística
('Secundaria', '1ro', 'Educación Artística', 'BC1', 'Comunicativa', 'CE-EA1', 'Realiza procesos creativos utilizando técnicas y estilos artísticos, en relación con la intención comunicativa, expresando la síntesis de ideas, sentimientos y vivencias, tanto propias como presentes en obras diversas.'),
('Secundaria', '1ro', 'Educación Artística', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EA2', 'Crea obras artísticas a partir de los aspectos constitutivos de cada disciplina artística, identificando sus elementos formales.'),
('Secundaria', '1ro', 'Educación Artística', 'BC2', 'Resolución de Problemas', 'CE-EA3', 'Argumenta sobre la función de distintos lenguajes artísticos en la construcción histórica de la sociedad en los contextos diversos.'),
('Secundaria', '1ro', 'Educación Artística', 'BC4', 'Ética y Ciudadana', 'CE-EA4', 'Comunica ideas, emociones, sentimientos y vivencias, a través de géneros, técnicas y estilos de diversas manifestaciones artísticas, valorando la capacidad comunicativa de estas de acuerdo con el contexto.'),
('Secundaria', '1ro', 'Educación Artística', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EA7', 'Reconoce críticamente manifestaciones artísticas multidisciplinares, identificando sus componentes e influencias, y reconociendo su trascendencia.'),
('Secundaria', '1ro', 'Educación Artística', 'BC3', 'Científica y Tecnológica', 'CE-EA5', 'Identifica recursos tecnológicos de diferentes lenguajes artísticos en la realización o análisis de producciones artísticas.'),
('Secundaria', '1ro', 'Educación Artística', 'BC3', 'Ambiental y de la Salud', 'CE-EA6', 'Reconoce las posibilidades técnicas que ofrecen las artes para la valoración y uso consciente de los recursos y espacios naturales.'),

-- Educación Física
('Secundaria', '1ro', 'Educación Física', 'BC1', 'Comunicativa', 'CE-EF1', 'Utiliza su cuerpo para expresar sentimientos, emociones y estados de ánimo en relación armónica con las demás personas y su entorno social y cultural.'),
('Secundaria', '1ro', 'Educación Física', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EF2', 'Muestra nivel de dominio en su acción motriz a partir de la noción de su esquema corporal, al percibir y apreciar patrones, tamaños, formas, direcciones y relaciones espaciales y temporales estáticas en entornos cercanos.'),
('Secundaria', '1ro', 'Educación Física', 'BC2', 'Resolución de Problemas', 'CE-EF3', 'Muestra niveles básicos de desempeño motriz en situaciones de juego, a partir de sus condiciones físicas naturales.'),
('Secundaria', '1ro', 'Educación Física', 'BC4', 'Ética y Ciudadana', 'CE-EF4', 'Realiza acciones motrices diversas en relación con los demás con respeto y responsabilidad.'),
('Secundaria', '1ro', 'Educación Física', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EF7', 'Identifica sus habilidades motrices y capacidades Físicas en el desarrollo de actividades corporales diversas, para utilizarlas en el juego y disfrutar de este.'),
('Secundaria', '1ro', 'Educación Física', 'BC3', 'Científica y Tecnológica', 'CE-EF5', 'Identifica las condiciones del perímetro de juegos y deportes, a fin de utilizarlas en relación con sus acciones motrices de la vida diaria.'),
('Secundaria', '1ro', 'Educación Física', 'BC3', 'Ambiental y de la Salud', 'CE-EF6', 'Reconoce algunos cambios en su cuerpo y sus habilidades motoras, con el objeto de valorarlas evitando situaciones de riesgo para su salud, la de los demás y de su entorno.'),

-- Formación Integral Humana y Religiosa
('Secundaria', '1ro', 'Formación Integral Humana y Religiosa', 'BC1', 'Comunicativa', 'CE-FIHR1', 'Constata el respeto a la vida presente en las manifestaciones culturales y religiosas de su familia y comunidad, a fin de promover y asimilar derechos humanos, valores morales y religiosos, en los diferentes contextos.'),
('Secundaria', '1ro', 'Formación Integral Humana y Religiosa', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-FIHR2', 'Presenta la importancia del trabajo, a fin de promover su implementación para la calidad de vida de las personas, la familia y la comunidad.'),
('Secundaria', '1ro', 'Formación Integral Humana y Religiosa', 'BC2', 'Resolución de Problemas', 'CE-FIHR3', 'Constata las principales dificultades que viven los adolescentes en su desarrollo y en sus relaciones sociales y familiares para buscar alternativas de solución a los conflictos que se les presenten.'),
('Secundaria', '1ro', 'Formación Integral Humana y Religiosa', 'BC4', 'Ética y Ciudadana', 'CE-FIHR4', 'Descubre en los evangelios la novedad de la vida y los valores practicados por Jesús de Nazaret, con la finalidad de compararlos con los asumidos en su familia, escuela y la comunidad e integrarlos en su relación con los demás.'),
('Secundaria', '1ro', 'Formación Integral Humana y Religiosa', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-FIHR7', 'Identifica los cambios físicos, emocionales, sexuales y espirituales de la etapa de la adolescencia, con la finalidad de afianzar su conocimiento personal y espiritual.'),
('Secundaria', '1ro', 'Formación Integral Humana y Religiosa', 'BC3', 'Científica y Tecnológica', 'CE-FIHR5', 'Constata la importancia de aplicar criterios éticos en el uso de las ciencias y las tecnologías, con el fin de mejorar la calidad de vida de las personas y del entorno natural.'),
('Secundaria', '1ro', 'Formación Integral Humana y Religiosa', 'BC3', 'Ambiental y de la Salud', 'CE-FIHR6', 'Identifica acciones a favor del cuidado de la vida, en todas sus manifestaciones, a fin de garantizar su salud personal y colectiva, desde los diferentes contextos.')
ON CONFLICT (nivel, grado, asignatura, competencia_fundamental) DO NOTHING;
